  // ../../src/campaign/wrap.ts
  var WORLD_WIDTH = world_americas_default.world.width;
  var wrapSpan = (g2) => g2.flags.world === 1 && g2.width >= WORLD_WIDTH - 0.5 ? WORLD_WIDTH : 0;
  function dxOf(g2, ax, bx) {
    const dx = Math.abs(ax - bx), span2 = wrapSpan(g2);
    return span2 > 0 && dx > span2 / 2 ? span2 - dx : dx;
  }
  var mapDist = (g2, ax, ay, bx, by2) => Math.hypot(dxOf(g2, ax, bx), ay - by2);
  var mapDist2 = (g2, ax, ay, bx, by2) => dxOf(g2, ax, bx) ** 2 + (ay - by2) ** 2;
  var CHART = world_americas_default.world;
  var RAD = Math.PI / 180;
  var KX = CHART.scale * Math.cos(CHART.parallel * RAD);
  var latOf = (y) => CHART.north - y / CHART.scale;
  function globeDist(g2, ax, ay, bx, by2) {
    const la = latOf(ay) * RAD, lb = latOf(by2) * RAD, dl = dxOf(g2, ax, bx) / KX * RAD;
    const h = Math.sin((la - lb) / 2) ** 2 + Math.cos(la) * Math.cos(lb) * Math.sin(dl / 2) ** 2;
    return 2 * Math.asin(Math.min(1, Math.sqrt(h))) / RAD * CHART.scale;
  }
  var WHOLE = world_whole_default;
  var FAR_FROM = WHOLE.first + WHOLE.stages[1];
