  var KX4 = Math.cos(50 * Math.PI / 180);
  function latLonOf(x, y) {
    const lat = 71.4 - y / 40;
    const lon = -11 + x / (KX4 * 40);
    return [lat, ((lon + 180) % 360 + 360) % 360 - 180];
  }
  var inBox = (lat, lon, b) => lat >= b.latS && lat <= b.latN && (b.lonW <= b.lonE ? lon >= b.lonW && lon <= b.lonE : lon >= b.lonW || lon <= b.lonE);
  function cloudZone(lat, lon) {
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return ZONES.find((z) => inBox(lat, lon, z.box)) ?? null;
  }
